#include <iostream>
#include <string>

int checkPossibility(const std::string& arr, int len, int end1, int end2);
int getDigit(char c);

int main() {
    std::string input;
    std::getline(std::cin, input);
    int len = input.length();
    int totalCount = 0;

    if (len == 1) {
        if (input[0] == 'X' || input[0] == '_' || getDigit(input[0]) == 0) {
            totalCount = 1;
        }
    } else {
        totalCount += checkPossibility(input, len, 2, 5);
        totalCount += checkPossibility(input, len, 5, 0);
        totalCount += checkPossibility(input, len, 7, 5);
        totalCount += checkPossibility(input, len, 0, 0);
    }

    std::cout << totalCount << std::endl;
    return 0;
}

int checkPossibility(const std::string& arr, int len, int end1, int end2) {
    if (len == 2 && end1 == 0) return 0;

    int X_value = -1;
    if (arr[len - 2] == 'X') {
        X_value = end1;
    } else {
        if (arr[len - 2] != '_') {
            if (getDigit(arr[len - 2]) != end1) return 0;
        }
    }

    if (arr[len - 1] == 'X') {
        if (X_value != -1 && end2 != X_value) return 0;
        else X_value = end2;
    } else {
        if (arr[len - 1] != '_') {
            if (getDigit(arr[len - 1]) != end2) return 0;
        }
    }

    int ways = 1;
    for (int i = 0; i < len - 2; i++) {
        if (i == 0) {
            if (arr[i] == 'X' && X_value == 0) return 0;
            if (getDigit(arr[i]) == 0) return 0;
        }
        if (arr[i] == '_') {
            ways *= (i == 0) ? 9 : 10;
        }
        if (arr[i] == 'X') {
            if (X_value != -1) continue;
            else {
                X_value = 10;
                ways *= (i == 0) ? 9 : 10;
            }
        }
    }
    return ways;
}

int getDigit(char c) {
    if (c == '_' || c == 'X') return -1;
    return c - '0';
}

